// Parser la commande Telegram
const text = $input.item.json.message.text;
const parts = text.split(' ');
const command = parts[0].replace('/', '').toLowerCase();
const subject = parts.slice(1).join(' ').trim();

// Mapping commande → catégorie
const categoryMap = {
  'excellence': {
    name: 'Excellence Opérationnelle',
    id: 1,
    emoji: '🔵'
  },
  'transformation': {
    name: 'Transformation Digitale',
    id: 2,
    emoji: '🟣'
  },
  'ia': {
    name: 'Intelligence Artificielle & Innovation',
    id: 3,
    emoji: '🔴'
  },
  'finance': {
    name: 'Finance & IA',
    id: 4,
    emoji: '🟢'
  },
  'marketing': {
    name: 'Marketing Automation & Data',
    id: 5,
    emoji: '🟠'
  },
  'rh': {
    name: 'RH & Talent Management',
    id: 6,
    emoji: '🔷'
  },
  'strategie': {
    name: 'Stratégie & Gouvernance IA',
    id: 7,
    emoji: '⚫'
  }
};

// Déterminer la catégorie
let category = null;
let forceCategory = false;

if (command === 'new') {
  // Mode automatique - Claude choisira
  category = null;
  forceCategory = false;
} else if (categoryMap[command]) {
  // Catégorie forcée
  category = categoryMap[command];
  forceCategory = true;
} else {
  // Commande inconnue
  return [{
    json: {
      error: true,
      message: `Commande inconnue: /${command}`,
      chat_id: $input.item.json.message.chat.id
    }
  }];
}

// Vérifier qu'il y a un sujet
if (!subject || subject.length < 10) {
  return [{
    json: {
      error: true,
      message: `❌ Veuillez fournir un sujet d'article.\n\nExemple: /${command} GPT-5 vient de sortir`,
      chat_id: $input.item.json.message.chat.id
    }
  }];
}

return [{
  json: {
    command: command,
    subject: subject,
    category: category,
    forceCategory: forceCategory,
    chat_id: $input.item.json.message.chat.id,
    user_id: $input.item.json.message.from.id,
    user_name: $input.item.json.message.from.first_name
  }
}];

